t.getiterator.php" class="methodname" style="color:#CC7832">getIterator</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.iterator.php" class="type Iterator" style="color:#EAB766">Iterator</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-tokenlist.item.php" class="methodname" style="color:#CC7832">item</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-tokenlist.remove.php" class="methodname" style="color:#CC7832">remove</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">...\$tokens</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-tokenlist.replace.php" class="methodname" style="color:#CC7832">replace</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$token</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$newToken</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-tokenlist.supports.php" class="methodname" style="color:#CC7832">supports</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$token</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-tokenlist.toggle.php" class="methodname" style="color:#CC7832">toggle</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$token</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span> <span class="parameter" style="color:#3A95FF">\$force</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>   }</div>  </div>  <div class="section" id="dom-tokenlist.props">   <h2 class="title">属性</h2>   <dl>         <dt id="dom-tokenlist.props.length"><var class="varname">length</var></dt>     <dd>      <span class="simpara">The number of tokens.</span>     </dd>             <dt id="dom-tokenlist.props.value"><var class="varname">value</var></dt>     <dd>      <span class="simpara">The value of the attribute linked to this object.</span>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">注释</h2>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:  <span class="simpara">  此 DOM 扩展在处理方法或属性时使用 UTF-8 编码。  解析器方法会自动检测编码，或允许调用者指定编码。 </span></p></blockquote>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">     Tokens in the list can be accessed by array syntax.    </span>   </p></blockquote>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Dom\TokenList::add} — Adds the given tokens to the list</li><li>{@link Dom\TokenList::contains} — Returns whether the list contains a given token</li><li>{@link Dom\TokenList::count} — Returns the number of tokens in the list</li><li>{@link Dom\TokenList::getIterator} — Returns an iterator over the token list</li><li>{@link Dom\TokenList::item} — Returns a token from the list</li><li>{@link Dom\TokenList::remove} — Removes the given tokens from the list</li><li>{@link Dom\TokenList::replace} — Replaces a token in the list with another one</li><li>{@link Dom\TokenList::supports} — Returns whether the given token is supported</li><li>{@link Dom\TokenList::toggle} — Toggles the presence of a token in the list</li></ul></div>
 * 
 * @since 8.4
 */
final class TokenList implements \IteratorAggregate, \Countable
{

    private function __construct() {}
    public int $length;

/**
 * <div id="dom-tokenlist.item" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\TokenList::item</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\TokenList::item</span> — <span class="dc-title">Returns a token from the list</span></p> </div> <div class="refsect1 description" id="refsect1-dom-tokenlist.item-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::item</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div>  <p class="simpara">   Returns a token from the list at <span class="parameter" style="color:#3A95FF">index</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-tokenlist.item-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>     <span class="simpara">      The token index.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-tokenlist.item-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the token at <span class="parameter" style="color:#3A95FF">index</span> or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> when the index   is out of bounds.  </p> </div> <div class="refsect1 examples" id="refsect1-dom-tokenlist.item-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-tokenlist.item.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::item()</strong></span> example</strong></p>   <div class="example-contents"><p>    Accesses a valid index and an invalid index.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">'&lt;p class="font-bold important"&gt;&lt;/p&gt;'</span><span style="color: #007700">, </span><span style="color: #9876AA">LIBXML_NOERROR</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$p </span><span style="color: #007700">= </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">body</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">firstChild</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$classList </span><span style="color: #007700">= </span><span style="color: #9876AA">\$p</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">classList</span><span style="color: #007700">;<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">\$classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">item</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">item</span><span style="color: #007700">(</span><span style="color: #9876AA">100</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">string(9)&nbsp;"font-bold"<br>NULL</blockquote></div>   </div>  </div> </div> <div class="refsect1 notes" id="refsect1-dom-tokenlist.item-notes">  <h3 class="title">注释</h3>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    This method is equivalent to using array access syntax.   </span>  </p></blockquote> </div></div>
 */
    public function item(int $index): ?string {}

/**
 * <div id="dom-tokenlist.contains" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\TokenList::contains</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\TokenList::contains</span> — <span class="dc-title">Returns whether the list contains a given token</span></p> </div> <div class="refsect1 description" id="refsect1-dom-tokenlist.contains-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::contains</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$token</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Returns whether the list contains <span class="parameter" style="color:#3A95FF">token</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-tokenlist.contains-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">token</span></dt>    <dd>     <span class="simpara">      The token.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-tokenlist.contains-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the list contains <span class="parameter" style="color:#3A95FF">token</span>,   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-dom-tokenlist.contains-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-tokenlist.contains.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::contains()</strong></span> example</strong></p>   <div class="example-contents"><p>    Checks whether two classes are present on the paragraph.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">'&lt;p class="font-bold important"&gt;&lt;/p&gt;'</span><span style="color: #007700">, </span><span style="color: #9876AA">LIBXML_NOERROR</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$p </span><span style="color: #007700">= </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">body</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">firstChild</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$classList </span><span style="color: #007700">= </span><span style="color: #9876AA">\$p</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">classList</span><span style="color: #007700">;<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">\$classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #DD0000">'important'</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #DD0000">'font-small'</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">bool(true)<br>bool(false)</blockquote></div>   </div>  </div> </div></div>
 */
    public function contains(string $token): bool {}

/**
 * <div id="dom-tokenlist.add" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\TokenList::add</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\TokenList::add</span> — <span class="dc-title">Adds the given tokens to the list</span></p> </div> <div class="refsect1 description" id="refsect1-dom-tokenlist.add-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::add</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">...\$tokens</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Adds the given <span class="parameter" style="color:#3A95FF">tokens</span> to the list, but not any that   were already present.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-tokenlist.add-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">tokens</span></dt>    <dd>     <span class="simpara">      The tokens to add.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-tokenlist.add-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-tokenlist.add-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist"> <li class="listitem">  <span class="simpara">   如果 token 包含 null 字节，抛出 <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span>。  </span> </li> <li class="listitem">  <span class="simpara">   如果 token 是空字符串，抛出 code 为 <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-syntax-err">Dom\SYNTAX_ERR</a></span></strong>   的 <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span>。  </span> </li> <li class="listitem">  <span class="simpara">   如果 token 包含 ASCII 空格，抛出 code 为 <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-invalid-character-err">Dom\INVALID_CHARACTER_ERR</a></span></strong>   的 <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span>。  </span> </li></ul> </div> <div class="refsect1 examples" id="refsect1-dom-tokenlist.add-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-tokenlist.add.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::add()</strong></span> example</strong></p>   <div class="example-contents"><p>    Adds two classes to a newly created paragraph element.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createEmpty</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$p </span><span style="color: #007700">= </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createElement</span><span style="color: #007700">(</span><span style="color: #DD0000">'p'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$classList </span><span style="color: #007700">= </span><span style="color: #9876AA">\$p</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">classList</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'font-bold'</span><span style="color: #007700">, </span><span style="color: #DD0000">'important'</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveHtml</span><span style="color: #007700">(</span><span style="color: #9876AA">\$p</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;p&nbsp;class="font-bold&nbsp;important"&gt;&lt;/p&gt;</blockquote></div>   </div>  </div> </div></div>
 */
    public function add(string ...$tokens): void {}

/**
 * <div id="dom-tokenlist.remove" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\TokenList::remove</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\TokenList::remove</span> — <span class="dc-title">Removes the given tokens from the list</span></p> </div> <div class="refsect1 description" id="refsect1-dom-tokenlist.remove-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::remove</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">...\$tokens</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Removes the given <span class="parameter" style="color:#3A95FF">tokens</span> from the list, but ignores   any that were not present.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-tokenlist.remove-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">tokens</span></dt>    <dd>     <span class="simpara">      The tokens to remove.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-tokenlist.remove-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-tokenlist.remove-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist"> <li class="listitem">  <span class="simpara">   如果 token 包含 null 字节，抛出 <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span>。  </span> </li> <li class="listitem">  <span class="simpara">   如果 token 是空字符串，抛出 code 为 <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-syntax-err">Dom\SYNTAX_ERR</a></span></strong>   的 <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span>。  </span> </li> <li class="listitem">  <span class="simpara">   如果 token 包含 ASCII 空格，抛出 code 为 <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-invalid-character-err">Dom\INVALID_CHARACTER_ERR</a></span></strong>   的 <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span>。  </span> </li></ul> </div> <div class="refsect1 examples" id="refsect1-dom-tokenlist.remove-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-tokenlist.remove.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::remove()</strong></span> example</strong></p>   <div class="example-contents"><p>    Removes two classes from the paragraph.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">'&lt;p class="font-bold important"&gt;&lt;/p&gt;'</span><span style="color: #007700">, </span><span style="color: #9876AA">LIBXML_NOERROR</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$p </span><span style="color: #007700">= </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">body</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">firstChild</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$p</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #DD0000">'font-bold'</span><span style="color: #007700">, </span><span style="color: #DD0000">'important'</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveHtml</span><span style="color: #007700">(</span><span style="color: #9876AA">\$p</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;p&nbsp;class=""&gt;&lt;/p&gt;</blockquote></div>   </div>  </div> </div></div>
 */
    public function remove(string ...$tokens): void {}

/**
 * <div id="dom-tokenlist.toggle" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\TokenList::toggle</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\TokenList::toggle</span> — <span class="dc-title">Toggles the presence of a token in the list</span></p> </div> <div class="refsect1 description" id="refsect1-dom-tokenlist.toggle-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::toggle</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$token</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></span> <span class="parameter" style="color:#3A95FF">\$force</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Toggles the presence of <span class="parameter" style="color:#3A95FF">token</span> in the list.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-tokenlist.toggle-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">token</span></dt>    <dd>     <span class="simpara">      The token to toggle.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">force</span></dt>    <dd>     <span class="simpara">      If <span class="parameter" style="color:#3A95FF">force</span> is provided, setting it to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> will      add the token, and setting it to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> will remove the token.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-tokenlist.toggle-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the token is in the list after the call,   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-tokenlist.toggle-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist"> <li class="listitem">  <span class="simpara">   如果 token 包含 null 字节，抛出 <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span>。  </span> </li> <li class="listitem">  <span class="simpara">   如果 token 是空字符串，抛出 code 为 <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-syntax-err">Dom\SYNTAX_ERR</a></span></strong>   的 <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span>。  </span> </li> <li class="listitem">  <span class="simpara">   如果 token 包含 ASCII 空格，抛出 code 为 <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-invalid-character-err">Dom\INVALID_CHARACTER_ERR</a></span></strong>   的 <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span>。  </span> </li></ul> </div> <div class="refsect1 examples" id="refsect1-dom-tokenlist.toggle-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-tokenlist.toggle.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::toggle()</strong></span> example</strong></p>   <div class="example-contents"><p>    Toggles three classes, two without <span class="parameter" style="color:#3A95FF">force</span>, and one with.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">'&lt;p class="font-bold important"&gt;&lt;/p&gt;'</span><span style="color: #007700">, </span><span style="color: #9876AA">LIBXML_NOERROR</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$p </span><span style="color: #007700">= </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">body</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">firstChild</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$classList </span><span style="color: #007700">= </span><span style="color: #9876AA">\$p</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">classList</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toggle</span><span style="color: #007700">(</span><span style="color: #DD0000">'font-bold'</span><span style="color: #007700">, </span><span style="color: #DD0000">'font-small'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toggle</span><span style="color: #007700">(</span><span style="color: #DD0000">'important'</span><span style="color: #007700">, </span><span style="color: #9876AA">force</span><span style="color: #007700">: </span><span style="color: #9876AA">true</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveHtml</span><span style="color: #007700">(</span><span style="color: #9876AA">\$p</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;p&nbsp;class="font-bold&nbsp;important"&gt;&lt;/p&gt;</blockquote></div>   </div>  </div> </div></div>
 */
    public function toggle(string $token, ?bool $force = null): bool {}

/**
 * <div id="dom-tokenlist.replace" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\TokenList::replace</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\TokenList::replace</span> — <span class="dc-title">Replaces a token in the list with another one</span></p> </div> <div class="refsect1 description" id="refsect1-dom-tokenlist.replace-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::replace</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$token</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$newToken</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Replaces a token in the list with another one.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-tokenlist.replace-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">token</span></dt>    <dd>     <span class="simpara">      The token to replace.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">newToken</span></dt>    <dd>     <span class="simpara">      The new token.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-tokenlist.replace-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if <span class="parameter" style="color:#3A95FF">token</span> was in the list,   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-tokenlist.replace-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist"> <li class="listitem">  <span class="simpara">   如果 token 包含 null 字节，抛出 <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span>。  </span> </li> <li class="listitem">  <span class="simpara">   如果 token 是空字符串，抛出 code 为 <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-syntax-err">Dom\SYNTAX_ERR</a></span></strong>   的 <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span>。  </span> </li> <li class="listitem">  <span class="simpara">   如果 token 包含 ASCII 空格，抛出 code 为 <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-invalid-character-err">Dom\INVALID_CHARACTER_ERR</a></span></strong>   的 <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span>。  </span> </li></ul> </div> <div class="refsect1 examples" id="refsect1-dom-tokenlist.replace-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-tokenlist.replace.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::replace()</strong></span> example</strong></p>   <div class="example-contents"><p>    Replaces a token in the paragraph with another one.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">'&lt;p class="font-bold important"&gt;&lt;/p&gt;'</span><span style="color: #007700">, </span><span style="color: #9876AA">LIBXML_NOERROR</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$p </span><span style="color: #007700">= </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">body</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">firstChild</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$p</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">classList</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">replace</span><span style="color: #007700">(</span><span style="color: #DD0000">'font-bold'</span><span style="color: #007700">, </span><span style="color: #DD0000">'font-small'</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveHtml</span><span style="color: #007700">(</span><span style="color: #9876AA">\$p</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;p&nbsp;class="font-small&nbsp;important"&gt;&lt;/p&gt;</blockquote></div>   </div>  </div> </div></div>
 */
    public function replace(string $token, string $newToken): bool {}

/**
 * <div id="dom-tokenlist.supports" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\TokenList::supports</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\TokenList::supports</span> — <span class="dc-title">Returns whether the given token is supported</span></p> </div> <div class="refsect1 description" id="refsect1-dom-tokenlist.supports-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::supports</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$token</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Returns whether <span class="parameter" style="color:#3A95FF">token</span> is in the   associated attribute's supported tokens.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-tokenlist.supports-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">token</span></dt>    <dd>     <span class="simpara">      The token.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-tokenlist.supports-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   成功时返回 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>， 或者在失败时返回 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-tokenlist.supports-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.typeerror.php" class="exceptionname">TypeError</a></span> when the attribute does   not define a supported tokens list.  </p> </div></div>
 */
    public function supports(string $token): bool {}
    public string $value;

/**
 * <div id="dom-tokenlist.count" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\TokenList::count</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\TokenList::count</span> — <span class="dc-title">Returns the number of tokens in the list</span></p> </div> <div class="refsect1 description" id="refsect1-dom-tokenlist.count-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\TokenList::count</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   Returns the number of tokens in the list.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-tokenlist.count-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-dom-tokenlist.count-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The number of tokens in the list.  </p> </div></div>
 */
    public function count(): int {}

