/**
 * <div id="class.dom-parentnode" class="reference"> <h1 class="title">The Dom\ParentNode interface</h1>  <div class="partintro"><p class="verinfo">(PHP 8 &gt;= 8.4.0)</p>  <div class="section" id="dom-parentnode.intro">   <h2 class="title">简介</h2>   <p class="simpara">    This is the modern, spec-compliant equivalent of    <span class="classname"><a href="https://php.net/manual/zh/class.domparentnode.php" class="classname">DOMParentNode</a></span>.   </p>  </div>  <div class="section" id="dom-parentnode.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">         <span class="modifier">interface</span> <strong class="interfacename"><strong class="interfacename">Dom\ParentNode</strong></strong> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis">     <span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-htmlcollection.php" class="type Dom\HTMLCollection" style="color:#EAB766">Dom\HTMLCollection</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-parentnode.php#dom-parentnode.props.children">\$<var class="varname">children</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-parentnode.append.php" class="methodname" style="color:#CC7832">append</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-parentnode.prepend.php" class="methodname" style="color:#CC7832">prepend</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-parentnode.queryselector.php" class="methodname" style="color:#CC7832">querySelector</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$selectors</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-element.php" class="type Dom\Element" style="color:#EAB766">Dom\Element</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-parentnode.queryselectorall.php" class="methodname" style="color:#CC7832">querySelectorAll</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$selectors</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-nodelist.php" class="type Dom\NodeList" style="color:#EAB766">Dom\NodeList</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-parentnode.replacechildren.php" class="methodname" style="color:#CC7832">replaceChildren</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section" id="dom-parentnode.props">   <h2 class="title">属性</h2>   <dl>         <dt id="dom-parentnode.props.children"><var class="varname">children</var></dt>     <dd>      <span class="simpara">       A <span class="classname"><a href="https://php.net/manual/zh/class.dom-htmlcollection.php" class="classname">Dom\HTMLCollection</a></span> containing all child       elements of this node. Available as of PHP 8.5.0.      </span>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Dom\ParentNode::append} — Appends nodes after the last child node</li><li>{@link Dom\ParentNode::prepend} — Prepends nodes before the first child node</li><li>{@link Dom\ParentNode::querySelector} — Returns the first element that matches the CSS selectors</li><li>{@link Dom\ParentNode::querySelectorAll} — Returns a collection of elements that match the CSS selectors</li><li>{@link Dom\ParentNode::replaceChildren} — Replace children in node</li></ul></div>
 * 
 * @since 8.4
 */
interface ParentNode
{
/**
 * <div id="dom-parentnode.append" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\ParentNode::append</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\ParentNode::append</span> — <span class="dc-title">Appends nodes after the last child node</span></p> </div> <div class="refsect1 description" id="refsect1-dom-parentnode.append-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\ParentNode::append</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Appends one or many <span class="parameter" style="color:#3A95FF">nodes</span> to the list of children after the last child node.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-parentnode.append-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">nodes</span></dt>     <dd>      <p class="para">       The nodes to append.       Strings are automatically converted to text nodes.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-dom-parentnode.append-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-parentnode.append-errors">  <h3 class="title">错误／异常</h3>  <dl>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-hierarchy-request-err">DOM_HIERARCHY_REQUEST_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if this node is of a type that does not allow children of the    type of one of the passed <span class="parameter" style="color:#3A95FF">nodes</span>, or if the node to    put in is one of this node's ancestors or this node itself.  </span> </dd>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-wrong-document-err">DOM_WRONG_DOCUMENT_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if one of the passed <span class="parameter" style="color:#3A95FF">nodes</span> was created from a different    document than the one that created this node.  </span> </dd>  </dl> </div> <div class="refsect1 seealso" id="refsect1-dom-parentnode.append-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\ParentNode::prepend()} - Prepends nodes before the first child node</span></li>  </ul> </div></div>
 */
    public function append(Node|string ...$nodes): void;

/**
 * <div id="dom-parentnode.prepend" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\ParentNode::prepend</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\ParentNode::prepend</span> — <span class="dc-title">Prepends nodes before the first child node</span></p> </div> <div class="refsect1 description" id="refsect1-dom-parentnode.prepend-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\ParentNode::prepend</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Prepends one or many <span class="parameter" style="color:#3A95FF">nodes</span> to the list of children before the first child node.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-parentnode.prepend-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">nodes</span></dt>     <dd>      <p class="para">       The nodes to prepend.       Strings are automatically converted to text nodes.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-dom-parentnode.prepend-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-parentnode.prepend-errors">  <h3 class="title">错误／异常</h3>  <dl>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-hierarchy-request-err">DOM_HIERARCHY_REQUEST_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if this node is of a type that does not allow children of the    type of one of the passed <span class="parameter" style="color:#3A95FF">nodes</span>, or if the node to    put in is one of this node's ancestors or this node itself.  </span> </dd>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-wrong-document-err">DOM_WRONG_DOCUMENT_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if one of the passed <span class="parameter" style="color:#3A95FF">nodes</span> was created from a different    document than the one that created this node.  </span> </dd>  </dl> </div> <div class="refsect1 seealso" id="refsect1-dom-parentnode.prepend-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\ParentNode::append()} - Appends nodes after the last child node</span></li>  </ul> </div></div>
 */
    public function prepend(Node|string ...$nodes): void;

/**
 * <div id="dom-parentnode.replacechildren" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\ParentNode::replaceChildren</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\ParentNode::replaceChildren</span> — <span class="dc-title">Replace children in node</span></p> </div> <div class="refsect1 description" id="refsect1-dom-parentnode.replacechildren-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\ParentNode::replaceChildren</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Replace children in node.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-parentnode.replacechildren-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">nodes</span></dt>     <dd>      <p class="para">       The nodes replacing the children.       Strings are automatically converted to text nodes.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-dom-parentnode.replacechildren-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-parentnode.replacechildren-errors">  <h3 class="title">错误／异常</h3>  <dl>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-hierarchy-request-err">DOM_HIERARCHY_REQUEST_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if this node is of a type that does not allow children of the    type of one of the passed <span class="parameter" style="color:#3A95FF">nodes</span>, or if the node to    put in is one of this node's ancestors or this node itself.  </span> </dd>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-wrong-document-err">DOM_WRONG_DOCUMENT_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if one of the passed <span class="parameter" style="color:#3A95FF">nodes</span> was created from a different    document than the one that created this node.  </span> </dd>  </dl> </div> <div class="refsect1 examples" id="refsect1-dom-parentnode.replacechildren-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\ParentNode::replaceChildren()</strong></span> example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">'&lt;!DOCTYPE HTML&gt;&lt;html&gt;&lt;p&gt;hi&lt;/p&gt; test &lt;p&gt;hi2&lt;/p&gt;&lt;/html&gt;'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">documentElement</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">replaceChildren</span><span style="color: #007700">(</span><span style="color: #DD0000">'foo'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createElement</span><span style="color: #007700">(</span><span style="color: #DD0000">'p'</span><span style="color: #007700">), </span><span style="color: #DD0000">'bar'</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveHtml</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;!DOCTYPE&nbsp;html&gt;&lt;html&gt;foo&lt;p&gt;&lt;/p&gt;bar&lt;/html&gt;</blockquote></div>   </div>  </div> </div></div>
 */
    public function replaceChildren(Node|string ...$nodes): void;

/**
 * <div id="dom-parentnode.queryselector" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\ParentNode::querySelector</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\ParentNode::querySelector</span> — <span class="dc-title">Returns the first element that matches the CSS selectors</span></p> </div> <div class="refsect1 description" id="refsect1-dom-parentnode.queryselector-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\ParentNode::querySelector</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$selectors</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-element.php" class="type Dom\Element" style="color:#EAB766">Dom\Element</a></span></span></div>  <p class="simpara">   Returns the first element that matches the CSS selectors specified   in <span class="parameter" style="color:#3A95FF">selectors</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-parentnode.queryselector-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">selectors</span></dt>    <dd>     <span class="simpara">      A string containing one or more CSS selectors.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-parentnode.queryselector-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the first <span class="classname"><a href="https://php.net/manual/zh/class.dom-element.php" class="classname">Dom\Element</a></span> that matches   <span class="parameter" style="color:#3A95FF">selectors</span>. Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if no element matches.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-parentnode.queryselector-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.domexception.php" class="exceptionname">DOMException</a></span> with code   <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-syntax-err">Dom\SYNTAX_ERR</a></span></strong> when <span class="parameter" style="color:#3A95FF">selectors</span>   is not a valid CSS selector string.  </p> </div> <div class="refsect1 seealso" id="refsect1-dom-parentnode.queryselector-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\ParentNode::querySelectorAll()} - Returns a collection of elements that match the CSS selectors</span></li>  </ul> </div></div>
 */
    public function querySelector(string $selectors): ?Element;

/**
 * <div id="dom-parentnode.queryselectorall" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\ParentNode::querySelectorAll</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\ParentNode::querySelectorAll</span> — <span class="dc-title">Returns a collection of elements that match the CSS selectors</span></p> </div> <div class="refsect1 description" id="refsect1-dom-parentnode.queryselectorall-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\ParentNode::querySelectorAll</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$selectors</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-nodelist.php" class="type Dom\NodeList" style="color:#EAB766">Dom\NodeList</a></span></div>  <p class="simpara">   Returns a collection of elements that match the CSS selectors specified   in <span class="parameter" style="color:#3A95FF">selectors</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-parentnode.queryselectorall-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">selectors</span></dt>    <dd>     <span class="simpara">      A string containing one or more CSS selectors.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-parentnode.queryselectorall-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a static collection of elements that match the CSS selectors   specified in <span class="parameter" style="color:#3A95FF">selectors</span>.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-parentnode.queryselectorall-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.domexception.php" class="exceptionname">DOMException</a></span> with code   <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-syntax-err">Dom\SYNTAX_ERR</a></span></strong> when <span class="parameter" style="color:#3A95FF">selectors</span>   is not a valid CSS selector string.  </p> </div> <div class="refsect1 seealso" id="refsect1-dom-parentnode.queryselectorall-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\ParentNode::querySelector()} - Returns the first element that matches the CSS selectors</span></li>  </ul> </div></div>
 */
    public function querySelectorAll(string $selectors): NodeList;
}
/**
 * <div id="class.dom-childnode" class="reference"> <h1 class="title">The Dom\ChildNode interface</h1>  <div class="partintro"><p class="verinfo">(PHP 8 &gt;= 8.4.0)</p>  <div class="section" id="dom-childnode.intro">   <h2 class="title">简介</h2>   <p class="simpara">    This is the modern, spec-compliant equivalent of    <span class="classname"><a href="https://php.net/manual/zh/class.domchildnode.php" class="classname">DOMChildNode</a></span>.   </p>  </div>  <div class="section" id="dom-childnode.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">         <span class="modifier">interface</span> <strong class="interfacename"><strong class="interfacename">Dom\ChildNode</strong></strong> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-childnode.after.php" class="methodname" style="color:#CC7832">after</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-childnode.before.php" class="methodname" style="color:#CC7832">before</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-childnode.remove.php" class="methodname" style="color:#CC7832">remove</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-childnode.replacewith.php" class="methodname" style="color:#CC7832">replaceWith</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Dom\ChildNode::after} — Adds nodes after the node</li><li>{@link Dom\ChildNode::before} — Adds nodes before the node</li><li>{@link Dom\ChildNode::remove} — Removes the node</li><li>{@link Dom\ChildNode::replaceWith} — Replaces the node with new nodes</li></ul></div>
