/**
 * <div id="dom-childnode.remove" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\ChildNode::remove</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\ChildNode::remove</span> — <span class="dc-title">Removes the node</span></p> </div> <div class="refsect1 description" id="refsect1-dom-childnode.remove-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\ChildNode::remove</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Removes the node.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-childnode.remove-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-dom-childnode.remove-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 seealso" id="refsect1-dom-childnode.remove-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\ChildNode::after()} - Adds nodes after the node</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\ChildNode::before()} - Adds nodes before the node</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\ChildNode::replaceWith()} - Replaces the node with new nodes</span></li>   <li><span class="methodname" style="color:#CC7832"><strong>Dom\Node::removeChild()</strong></span></li>  </ul> </div></div>
 */
    public function remove(): void;

/**
 * <div id="dom-childnode.before" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\ChildNode::before</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\ChildNode::before</span> — <span class="dc-title">Adds nodes before the node</span></p> </div> <div class="refsect1 description" id="refsect1-dom-childnode.before-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\ChildNode::before</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Adds the passed <span class="parameter" style="color:#3A95FF">nodes</span> before the node.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-childnode.before-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">nodes</span></dt>     <dd>      <p class="para">       Nodes to be added before the node.       Strings are automatically converted to text nodes.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-dom-childnode.before-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-childnode.before-errors">  <h3 class="title">错误／异常</h3>  <dl>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-hierarchy-request-err">DOM_HIERARCHY_REQUEST_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if the parent is of a type that does not allow children of the    type of one of the passed <span class="parameter" style="color:#3A95FF">nodes</span>, or if the node to    put in is one of this node's ancestors or this node itself.  </span> </dd>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-wrong-document-err">DOM_WRONG_DOCUMENT_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if one of the passed <span class="parameter" style="color:#3A95FF">nodes</span> was created from a different    document than the one that created this node.  </span> </dd>  </dl> </div> <div class="refsect1 seealso" id="refsect1-dom-childnode.before-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\ChildNode::after()} - Adds nodes after the node</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\ChildNode::remove()} - Removes the node</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\ChildNode::replaceWith()} - Replaces the node with new nodes</span></li>  </ul> </div></div>
 */
