/div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.firstchild">\$<var class="varname">firstChild</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.lastchild">\$<var class="varname">lastChild</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.previoussibling">\$<var class="varname">previousSibling</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.nextsibling">\$<var class="varname">nextSibling</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.nodevalue">\$<var class="varname">nodeValue</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.textcontent">\$<var class="varname">textContent</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// Not documented yet </div>       }</div>  </div>  <div class="section" id="dom-node.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="dom-node.constants.document-position-disconnected">      <strong><span>{@link DOMNode::DOCUMENT_POSITION_DISCONNECTED}</span></strong>     </dt><dd>      <span class="simpara">       Set when the other node and reference node are not in the same tree.      </span>     </dd>             <dt id="dom-node.constants.document-position-preceding">      <strong><span>{@link DOMNode::DOCUMENT_POSITION_PRECEDING}</span></strong>     </dt><dd>      <span class="simpara">       Set when the other node precedes the reference node.      </span>     </dd>             <dt id="dom-node.constants.document-position-following">      <strong><span>{@link DOMNode::DOCUMENT_POSITION_FOLLOWING}</span></strong>     </dt><dd>      <span class="simpara">       Set when the other node follows the reference node.      </span>     </dd>             <dt id="dom-node.constants.document-position-contains">      <strong><span>{@link DOMNode::DOCUMENT_POSITION_CONTAINS}</span></strong>     </dt><dd>      <span class="simpara">       Set when the other node is an ancestor of the reference node.      </span>     </dd>             <dt id="dom-node.constants.document-position-contained-by">      <strong><span>{@link DOMNode::DOCUMENT_POSITION_CONTAINED_BY}</span></strong>     </dt><dd>      <span class="simpara">       Set when the other node is a descendant of the reference node.      </span>     </dd>             <dt id="dom-node.constants.document-position-implementation-specific">      <strong><span>{@link DOMNode::DOCUMENT_POSITION_IMPLEMENTATION_SPECIFIC}</span></strong>     </dt><dd>      <span class="simpara">       Set when the result depends on implementation-specific behaviour and       may not be portable.       This may happen with disconnected nodes or with attribute nodes.      </span>     </dd>       </dl>  </div>  <div class="section" id="dom-node.props">   <h2 class="title">属性</h2>   <dl>         <dt id="dom-node.props.nodetype"><var class="varname">nodeType</var></dt><dd>      <p class="para">Gets the type of the node. One of the predefined <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.xml-element-node">XML_<span class="replaceable">*</span>_NODE</a></span></strong> constants</p>     </dd>             <dt id="dom-node.props.nodename"><var class="varname">nodeName</var></dt>     <dd>      <span class="simpara">Returns the most accurate name for the current node type.</span>      <ul class="itemizedlist">       <li class="listitem"><span class="simpara">For elements, this is the HTML-uppercased qualified name.</span></li>       <li class="listitem"><span class="simpara">For attributes, this is the qualified name.</span></li>       <li class="listitem"><span class="simpara">For processing instructions, this is the target.</span></li>       <li class="listitem"><span class="simpara">For document type nodes, this is the name.</span></li>      </ul>     </dd>             <dt id="dom-node.props.baseuri"><var class="varname">baseURI</var></dt><dd>      <p class="para">       The absolute base URI of this node or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if the implementation       wasn't able to obtain an absolute URI.      </p>     </dd>             <dt id="dom-node.props.isconnected"><var class="varname">isConnected</var></dt><dd>      <p class="para">Whether the node is connected to a document</p>     </dd>             <dt id="dom-node.props.ownerdocument"><var class="varname">ownerDocument</var></dt>     <dd>      <span class="simpara">       The <span class="classname"><a href="https://php.net/manual/zh/class.dom-document.php" class="classname">Dom\Document</a></span> object associated with       this node, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if this node is a document.      </span>     </dd>             <dt id="dom-node.props.parentnode"><var class="varname">parentNode</var></dt><dd>      <p class="para">The parent of this node. If there is no such node, this returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.</p>     </dd>             <dt id="dom-node.props.parentelement"><var class="varname">parentElement</var></dt><dd>      <p class="para">The parent element of this element. If there is no such element, this returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.</p>     </dd>             <dt id="dom-node.props.childnodes"><var class="varname">childNodes</var></dt>     <dd>      <span class="simpara">       A <span class="classname"><a href="https://php.net/manual/zh/class.dom-nodelist.php" class="classname">Dom\NodeList</a></span> that contains all       children of this node. If there are no children, this is an empty       <span class="classname"><a href="https://php.net/manual/zh/class.dom-nodelist.php" class="classname">Dom\NodeList</a></span>.      </span>     </dd>             <dt id="dom-node.props.firstchild"><var class="varname">firstChild</var></dt><dd>      <p class="para">       The first child of this node. If there is no such node, this       returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.      </p>     </dd>             <dt id="dom-node.props.lastchild"><var class="varname">lastChild</var></dt><dd>      <p class="para">The last child of this node. If there is no such node, this returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.</p>     </dd>             <dt id="dom-node.props.previoussibling"><var class="varname">previousSibling</var></dt><dd>      <p class="para">       The node immediately preceding this node. If there is no such       node, this returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.      </p>     </dd>             <dt id="dom-node.props.nextsibling"><var class="varname">nextSibling</var></dt><dd>      <p class="para">       The node immediately following this node. If there is no such       node, this returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.      </p>     </dd>             <dt id="dom-node.props.nodevalue"><var class="varname">nodeValue</var></dt>     <dd>      <span class="simpara">       The value of this node, depending on its type.      </span>     </dd>             <dt id="dom-node.props.textcontent"><var class="varname">textContent</var></dt><dd>      <p class="para">The text content of this node and its descendants.</p>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">注释</h2>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:  <span class="simpara">  此 DOM 扩展在处理方法或属性时使用 UTF-8 编码。  解析器方法会自动检测编码，或允许调用者指定编码。 </span></p></blockquote>  </div>  <div class="section">   <h2 class="title">参见</h2>   <ul class="simplelist">    <li><a href="https://dom.spec.whatwg.org/#interface-node" class="link external">»&nbsp;WHATWG specification of Node</a></li>   </ul>  </div> </div></div>
 * 
 * @since 8.4
 */
class Node
{

    final private function __construct() {}
    public int $nodeType;
    public string $nodeName;
    public string $baseURI;
    public bool $isConnected;
    public ?Document $ownerDocument;


    public function getRootNode(array $options = []): Node {}
    public ?Node $parentNode;
    public ?Element $parentElement;


    public function hasChildNodes(): bool {}

    /** @var NodeList<Node> */
    public NodeList $childNodes;
    public ?Node $firstChild;
    public ?Node $lastChild;
    public ?Node $previousSibling;
    public ?Node $nextSibling;
    public ?string $nodeValue;
    public ?string $textContent;


    public function normalize(): void {}


    public function cloneNode(bool $deep = false): Node {}


    public function isEqualNode(?Node $otherNode): bool {}


    public function isSameNode(?Node $otherNode): bool {}
    public const int DOCUMENT_POSITION_DISCONNECTED = 0x01;
    public const int DOCUMENT_POSITION_PRECEDING = 0x02;
    public const int DOCUMENT_POSITION_FOLLOWING = 0x04;
    public const int DOCUMENT_POSITION_CONTAINS = 0x08;
    public const int DOCUMENT_POSITION_CONTAINED_BY = 0x10;
    public const int DOCUMENT_POSITION_IMPLEMENTATION_SPECIFIC = 0x20;


    public function compareDocumentPosition(Node $other): int {}


    public function contains(?Node $other): bool {}


    public function lookupPrefix(?string $namespace): ?string {}


    public function lookupNamespaceURI(?string $prefix): ?string {}


    public function isDefaultNamespace(?string $namespace): bool {}


    public function insertBefore(Node $node, ?Node $child): Node {}


    public function appendChild(Node $node): Node {}


    public function replaceChild(Node $node, Node $child): Node {}


    public function removeChild(Node $child): Node {}


    public function getLineNo(): int {}


    public function getNodePath(): string {}


    public function C14N(bool $exclusive = false, bool $withComments = false, ?array $xpath = null, ?array $nsPrefixes = null): string|false {}


    public function C14NFile(string $uri, bool $exclusive = false, bool $withComments = false, ?array $xpath = null, ?array $nsPrefixes = null): int|false {}


    public function __sleep(): array {}


    public function __wakeup(): void {}
}
