final class HTMLDocument extends Document
{
/**
 * <div id="dom-htmldocument.createempty" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\HTMLDocument::createEmpty</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\HTMLDocument::createEmpty</span> — <span class="dc-title">Creates an empty <span>HTML</span> document</span></p> </div> <div class="refsect1 description" id="refsect1-dom-htmldocument.createempty-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\HTMLDocument::createEmpty</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$encoding</span><span class="initializer"> = "UTF-8"</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-htmldocument.php" class="type Dom\HTMLDocument" style="color:#EAB766">Dom\HTMLDocument</a></span></div>  <p class="simpara">   Creates an empty <span>HTML</span> document without any elements.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-htmldocument.createempty-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">encoding</span></dt>    <dd>     <span class="simpara">      The character encoding of the document, used for serialization when      calling the save methods.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-htmldocument.createempty-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   An empty <span>HTML</span> document.  </p> </div> <div class="refsect1 examples" id="refsect1-dom-htmldocument.createempty-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-htmldocument.createempty.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\HTMLDocument::createEmpty()</strong></span> example</strong></p>   <div class="example-contents"><p>    Creates an empty document and serializes it.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createEmpty</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveHtml</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">string(0)&nbsp;""</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-dom-htmldocument.createempty-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::createFromString()} - Parses an HTML document from a string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::createFromFile()} - Parses an HTML document from a file</span></li>  </ul> </div></div>
 */
    public static function createEmpty(string $encoding = "UTF-8"): HTMLDocument {}

/**
 * <div id="dom-htmldocument.createfromfile" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\HTMLDocument::createFromFile</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\HTMLDocument::createFromFile</span> — <span class="dc-title">Parses an <span>HTML</span> document from a file</span></p> </div> <div class="refsect1 description" id="refsect1-dom-htmldocument.createfromfile-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\HTMLDocument::createFromFile</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$path</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = 0</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$overrideEncoding</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-htmldocument.php" class="type Dom\HTMLDocument" style="color:#EAB766">Dom\HTMLDocument</a></span></div>  <p class="simpara">   Parses an <span>HTML</span> document from a file,   according to the living standard.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-htmldocument.createfromfile-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">path</span></dt>    <dd>     <span class="simpara">      The path to the file to parse.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <span class="simpara">  <a href="https://php.net/manual/zh/language.operators.bitwise.php" class="link">Bitwise <span class="literal">OR</span></a>  of the <a href="https://php.net/manual/zh/libxml.constants.php" class="link">libxml option constants</a>.</span> <span class="simpara">  It is also possible to pass <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-html-no-default-ns">Dom\HTML_NO_DEFAULT_NS</a></span></strong>  to disable the use of the HTML namespace and the template element.  This should only be used if the implications are properly understood.</span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">overrideEncoding</span></dt>    <dd>     <span class="simpara"> The encoding that the document was created in. If not provided, it will attempt to determine the encoding that is most likely used.</span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-htmldocument.createfromfile-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The parsed document as an <span class="classname"><a href="https://php.net/manual/zh/class.dom-htmldocument.php" class="classname">Dom\HTMLDocument</a></span> instance.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-htmldocument.createfromfile-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist">   <li class="listitem">    <span class="simpara">     Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if     <span class="parameter" style="color:#3A95FF">path</span> contains null bytes or contains     <span class="literal">"%00"</span>.    </span>   </li>   <li class="listitem"> <span class="simpara">  Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if  <span class="parameter" style="color:#3A95FF">options</span> contains an invalid option. </span></li><li class="listitem"> <span class="simpara">  Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if  <span class="parameter" style="color:#3A95FF">overrideEncoding</span> is an unknown encoding. </span></li>   <li class="listitem">    <span class="simpara">     Throws an <span class="exceptionname"><a href="https://php.net/manual/zh/class.exception.php" class="exceptionname">Exception</a></span> if     the file could not be opened.    </span>   </li>  </ul> </div> <div class="refsect1 notes" id="refsect1-dom-htmldocument.createfromfile-notes"> <h3 class="title">注释</h3> <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:   <span class="simpara">   Whitespace in the <span class="literal">html</span> and <span class="literal">head</span> tags   is not considered significant and may lose formatting.  </span> </p></blockquote></div> <div class="refsect1 seealso" id="refsect1-dom-htmldocument.createfromfile-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::createEmpty()} - Creates an empty HTML document</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::createFromString()} - Parses an HTML document from a string</span></li>  </ul> </div></div>
 */
    public static function createFromFile(string $path, int $options = 0, ?string $overrideEncoding = null): HTMLDocument {}

/**
 * <div id="dom-htmldocument.createfromstring" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\HTMLDocument::createFromString</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\HTMLDocument::createFromString</span> — <span class="dc-title">Parses an <span>HTML</span> document from a string</span></p> </div> <div class="refsect1 description" id="refsect1-dom-htmldocument.createfromstring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\HTMLDocument::createFromString</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$source</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = 0</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$overrideEncoding</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-htmldocument.php" class="type Dom\HTMLDocument" style="color:#EAB766">Dom\HTMLDocument</a></span></div>  <p class="simpara">   Parses an <span>HTML</span> document from a string,   according to the living standard.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-htmldocument.createfromstring-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">source</span></dt>    <dd>     <span class="simpara">      The string containing the <span>HTML</span> to parse.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <span class="simpara">  <a href="https://php.net/manual/zh/language.operators.bitwise.php" class="link">Bitwise <span class="literal">OR</span></a>  of the <a href="https://php.net/manual/zh/libxml.constants.php" class="link">libxml option constants</a>.</span> <span class="simpara">  It is also possible to pass <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-html-no-default-ns">Dom\HTML_NO_DEFAULT_NS</a></span></strong>  to disable the use of the HTML namespace and the template element.  This should only be used if the implications are properly understood.</span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">overrideEncoding</span></dt>    <dd>     <span class="simpara"> The encoding that the document was created in. If not provided, it will attempt to determine the encoding that is most likely used.</span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-htmldocument.createfromstring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The parsed document as an <span class="classname"><a href="https://php.net/manual/zh/class.dom-htmldocument.php" class="classname">Dom\HTMLDocument</a></span> instance.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-htmldocument.createfromstring-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist">   <li class="listitem"> <span class="simpara">  Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if  <span class="parameter" style="color:#3A95FF">options</span> contains an invalid option. </span></li><li class="listitem"> <span class="simpara">  Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if  <span class="parameter" style="color:#3A95FF">overrideEncoding</span> is an unknown encoding. </span></li>  </ul> </div> <div class="refsect1 examples" id="refsect1-dom-htmldocument.createfromstring-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-htmldocument.createfromstring.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\HTMLDocument::createFromString()</strong></span> example</strong></p>   <div class="example-contents"><p>    Parses a sample document.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$dom </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\HTMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(&lt;&lt;&lt;'HTML'<br></span><span style="color: #DD0000">&lt;!DOCTYPE html&gt;<br>&lt;html&gt;<br>&lt;body&gt;<br>   &lt;p&gt;Hello, world!&lt;/p&gt;<br>&lt;/body&gt;<br>&lt;/html&gt;<br></span><span style="color: #007700">HTML);<br>echo </span><span style="color: #9876AA">\$dom</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveHtml</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;!DOCTYPE&nbsp;html&gt;&lt;html&gt;&lt;head&gt;&lt;/head&gt;&lt;body&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;p&gt;Hello,&nbsp;world!&lt;/p&gt;<br><br>&lt;/body&gt;&lt;/html&gt;</blockquote></div>   </div>  </div> </div> <div class="refsect1 notes" id="refsect1-dom-htmldocument.createfromstring-notes"> <h3 class="title">注释</h3> <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:   <span class="simpara">   Whitespace in the <span class="literal">html</span> and <span class="literal">head</span> tags   is not considered significant and may lose formatting.  </span> </p></blockquote></div> <div class="refsect1 seealso" id="refsect1-dom-htmldocument.createfromstring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::createEmpty()} - Creates an empty HTML document</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::createFromFile()} - Parses an HTML document from a file</span></li>  </ul> </div></div>
 */
    public static function createFromString(string $source, int $options = 0, ?string $overrideEncoding = null): HTMLDocument {}

/**
 * <div id="dom-htmldocument.savexml" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\HTMLDocument::saveXml</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\HTMLDocument::saveXml</span> — <span class="dc-title">Serializes the document as an <span>XML</span> string</span></p> </div> <div class="refsect1 description" id="refsect1-dom-htmldocument.savexml-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\HTMLDocument::saveXml</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span></span> <span class="parameter" style="color:#3A95FF">\$node</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = 0</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.singleton.php" class="type false" style="color:#EAB766">false</a></span></span></div>  <p class="simpara">   Serializes the document as an <span>XML</span> string.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-htmldocument.savexml-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">node</span></dt>    <dd>     <span class="simpara">      The node to serialize.      If not provided, the entire document is serialized.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <span class="simpara"> Additional Options. The <strong><span><a href="https://php.net/manual/zh/libxml.constants.php#constant.libxml-noemptytag">LIBXML_NOEMPTYTAG</a></span></strong> and <strong><span><a href="https://php.net/manual/zh/libxml.constants.php#constant.libxml-noxmldecl">LIBXML_NOXMLDECL</a></span></strong> options are supported. Prior to PHP 8.3.0, only the <strong><span><a href="https://php.net/manual/zh/libxml.constants.php#constant.libxml-noemptytag">LIBXML_NOEMPTYTAG</a></span></strong> option is supported.</span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-htmldocument.savexml-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The serialized <span>XML</span> document string in the current   document encoding, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> on failure.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-htmldocument.savexml-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist">   <li class="listitem"> <span class="simpara">  Throws a <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span> with code  <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-wrong-document-err">Dom\WRONG_DOCUMENT_ERR</a></span></strong> if <span class="parameter" style="color:#3A95FF">node</span>  is from another document. </span></li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-dom-htmldocument.savexml-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::saveXmlFile()} - Serializes the document as an XML file</span></li>   <li><span class="methodname" style="color:#CC7832"><strong>Dom\XMLDocument::saveHtml()</strong></span></li>  </ul> </div></div>
 */
    public function saveXml(?Node $node = null, int $options = 0): string|false {}

/**
 * <div id="dom-htmldocument.savexmlfile" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\HTMLDocument::saveXmlFile</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\HTMLDocument::saveXmlFile</span> — <span class="dc-title">Serializes the document as an <span>XML</span> file</span></p> </div> <div class="refsect1 description" id="refsect1-dom-htmldocument.savexmlfile-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\HTMLDocument::saveXmlFile</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$filename</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = 0</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.singleton.php" class="type false" style="color:#EAB766">false</a></span></span></div>  <p class="simpara">   Serializes the document as an <span>XML</span> file.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-htmldocument.savexmlfile-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">filename</span></dt>    <dd>     <span class="simpara">      The path to the file to save to.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <span class="simpara"> Additional Options. The <strong><span><a href="https://php.net/manual/zh/libxml.constants.php#constant.libxml-noemptytag">LIBXML_NOEMPTYTAG</a></span></strong> and <strong><span><a href="https://php.net/manual/zh/libxml.constants.php#constant.libxml-noxmldecl">LIBXML_NOXMLDECL</a></span></strong> options are supported. Prior to PHP 8.3.0, only the <strong><span><a href="https://php.net/manual/zh/libxml.constants.php#constant.libxml-noemptytag">LIBXML_NOEMPTYTAG</a></span></strong> option is supported.</span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-htmldocument.savexmlfile-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The number of bytes written on success, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> on failure.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-htmldocument.savexmlfile-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist">   <li class="listitem">    <span class="simpara">     Throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if     <span class="parameter" style="color:#3A95FF">filename</span> is an empty string or contains any     null bytes.    </span>   </li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-dom-htmldocument.savexmlfile-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::saveXml()} - Serializes the document as an XML string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::saveHtmlFile()} - Serializes the document as an HTML file</span></li>  </ul> </div></div>
 */
    public function saveXmlFile(string $filename, int $options = 0): int|false {}

/**
 * <div id="dom-htmldocument.savehtml" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\HTMLDocument::saveHtml</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\HTMLDocument::saveHtml</span> — <span class="dc-title">Serializes the document as an <span>HTML</span> string</span></p> </div> <div class="refsect1 description" id="refsect1-dom-htmldocument.savehtml-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\HTMLDocument::saveHtml</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span></span> <span class="parameter" style="color:#3A95FF">\$node</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Serializes the document as an <span>HTML</span> string.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-htmldocument.savehtml-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">node</span></dt>    <dd>     <span class="simpara">      The node to serialize.      If not provided, the entire document is serialized.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-htmldocument.savehtml-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The serialized <span>HTML</span> document string in the current   document encoding.  </p> </div> <div class="refsect1 errors" id="refsect1-dom-htmldocument.savehtml-errors">  <h3 class="title">错误／异常</h3>  <ul class="itemizedlist">   <li class="listitem"> <span class="simpara">  Throws a <span class="exceptionname"><strong class="exceptionname">Dom\DOMException</strong></span> with code  <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-wrong-document-err">Dom\WRONG_DOCUMENT_ERR</a></span></strong> if <span class="parameter" style="color:#3A95FF">node</span>  is from another document. </span></li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-dom-htmldocument.savehtml-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::saveHtmlFile()} - Serializes the document as an HTML file</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\HTMLDocument::saveXml()} - Serializes the document as an XML string</span></li>  </ul> </div></div>
 */
    public function saveHtml(?Node $node = null): string {}

/**
