 * <div id="dom-characterdata.after" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\CharacterData::after</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\CharacterData::after</span> — <span class="dc-title">Adds nodes after the character data</span></p> </div> <div class="refsect1 description" id="refsect1-dom-characterdata.after-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\CharacterData::after</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">...\$nodes</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Adds the passed <span class="parameter" style="color:#3A95FF">nodes</span> after the character data.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-characterdata.after-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">nodes</span></dt>     <dd>      <p class="para">       Nodes to be added after the node.       Strings are automatically converted to text nodes.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-dom-characterdata.after-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-characterdata.after-errors">  <h3 class="title">错误／异常</h3>  <dl>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-hierarchy-request-err">DOM_HIERARCHY_REQUEST_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if the parent is of a type that does not allow children of the    type of one of the passed <span class="parameter" style="color:#3A95FF">nodes</span>, or if the node to    put in is one of this node's ancestors or this node itself.  </span> </dd>    <dt><strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-wrong-document-err">DOM_WRONG_DOCUMENT_ERR</a></span></strong></dt>  <dd>  <span class="simpara">    Raised if one of the passed <span class="parameter" style="color:#3A95FF">nodes</span> was created from a different    document than the one that created this node.  </span> </dd>  </dl> </div> <div class="refsect1 examples" id="refsect1-dom-characterdata.after-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-characterdata.after.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\CharacterData::after()</strong></span> example</strong></p>   <div class="example-contents"><p>    Adds nodes after the character data.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$doc </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\XMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">"&lt;container&gt;&lt;![CDATA[hello]]&gt;&lt;/container&gt;"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$cdata </span><span style="color: #007700">= </span><span style="color: #9876AA">\$doc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">documentElement</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">firstChild</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$cdata</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">after</span><span style="color: #007700">(</span><span style="color: #DD0000">"beautiful"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$doc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createElement</span><span style="color: #007700">(</span><span style="color: #DD0000">"world"</span><span style="color: #007700">));<br><br>echo </span><span style="color: #9876AA">\$doc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveXML</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;?xml&nbsp;version="1.0"&nbsp;encoding="UTF-8"?&gt;<br>&lt;container&gt;&lt;![CDATA[hello]]&gt;beautiful&lt;world/&gt;&lt;/container&gt;</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-dom-characterdata.after-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Dom\ChildNode::after()} - Adds nodes after the node</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Dom\CharacterData::before()} - Adds nodes before the character data</span></li>  </ul> </div></div>
 */
    public function after(Node|string ...$nodes): void {}

