 class="type string" style="color:#EAB766">string</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.nodename">\$<var class="varname">nodeName</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.baseuri">\$<var class="varname">baseURI</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.isconnected">\$<var class="varname">isConnected</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-document.php" class="type Dom\Document" style="color:#EAB766">Dom\Document</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.ownerdocument">\$<var class="varname">ownerDocument</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.parentnode">\$<var class="varname">parentNode</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-element.php" class="type Dom\Element" style="color:#EAB766">Dom\Element</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.parentelement">\$<var class="varname">parentElement</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-nodelist.php" class="type Dom\NodeList" style="color:#EAB766">Dom\NodeList</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.childnodes">\$<var class="varname">childNodes</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.firstchild">\$<var class="varname">firstChild</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.lastchild">\$<var class="varname">lastChild</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.previoussibling">\$<var class="varname">previousSibling</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.dom-node.php" class="type Dom\Node" style="color:#EAB766">Dom\Node</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.nextsibling">\$<var class="varname">nextSibling</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.nodevalue">\$<var class="varname">nodeValue</var></a></var>;</div><div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.dom-node.php#dom-node.props.textcontent">\$<var class="varname">textContent</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-attr.isid.php" class="methodname" style="color:#CC7832">isId</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/dom-attr.rename.php" class="methodname" style="color:#CC7832">rename</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$namespaceURI</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$qualifiedName</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 继承的方法 </div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// Not documented yet </div>       }</div>  </div>  <div class="section" id="dom-attr.props">   <h2 class="title">属性</h2>   <dl>         <dt id="dom-attr.props.namespaceuri"><var class="varname">namespaceURI</var></dt>     <dd>      <span class="simpara">The namespace <span>URI</span> of the attribute.</span>     </dd>             <dt id="dom-attr.props.prefix"><var class="varname">prefix</var></dt>     <dd>      <span class="simpara">The namespace prefix of the attribute.</span>     </dd>             <dt id="dom-attr.props.localname"><var class="varname">localName</var></dt>     <dd>      <span class="simpara">The local name of the attribute.</span>     </dd>             <dt id="dom-attr.props.name"><var class="varname">name</var></dt>     <dd>      <span class="simpara">The qualified name of the attribute.</span>     </dd>             <dt id="dom-attr.props.value"><var class="varname">value</var></dt>     <dd>      <span class="simpara">The value of the attribute.</span>      <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:        <span class="simpara">        Unlike the equivalent property in <span class="classname"><a href="https://php.net/manual/zh/class.domattr.php" class="classname">DOMAttr</a></span>,        this does not substitute entities.       </span>      </p></blockquote>     </dd>             <dt id="dom-attr.props.ownerelement"><var class="varname">ownerElement</var></dt>     <dd>      <span class="simpara">The element that contains the attribute or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.</span>     </dd>             <dt id="dom-attr.props.specified"><var class="varname">specified</var></dt>     <dd>      <span class="simpara">Legacy option, always is <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>.</span>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">参见</h2>   <ul class="simplelist">    <li><a href="https://dom.spec.whatwg.org/#interface-attr" class="link external">»&nbsp;WHATWG specification of Attr</a></li>   </ul>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Dom\Attr::isId} — Checks if attribute is a defined ID</li><li>{@link Dom\Attr::rename} — Changes the qualified name or namespace of an attribute</li></ul></div>
 * 
 * @since 8.4
 */
class Attr extends Node
{
    public ?string $namespaceURI;
    public ?string $prefix;
    public string $localName;
    public string $name;
    public string $value;
    public ?Element $ownerElement;
    public bool $specified;

/**
 * <div id="dom-attr.isid" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\Attr::isId</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\Attr::isId</span> — <span class="dc-title">   Checks if attribute is a defined ID  </span></p> </div> <div class="refsect1 description" id="refsect1-dom-attr.isid-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\Attr::isId</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">   This function checks if the attribute is a defined ID.  </p>  <p class="simpara">   According to the DOM standard this requires a DTD which defines the   attribute ID to be of type ID. To utilise this method the document   must be validated at parse time by passing   <strong><span><a href="https://php.net/manual/zh/libxml.constants.php#constant.libxml-dtdvalid">LIBXML_DTDVALID</a></span></strong> as an option.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-attr.isid-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-dom-attr.isid-returnvalues">  <h3 class="title">返回值</h3><p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if this attribute is a defined ID, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-dom-attr.isid-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 Dom\Attr::isId() Example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #FF8000">// We need to validate our document before referring to the id<br></span><span style="color: #9876AA">\$doc </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\XMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromFile</span><span style="color: #007700">(</span><span style="color: #DD0000">'examples/book-docbook.xml'</span><span style="color: #007700">, </span><span style="color: #9876AA">LIBXML_DTDVALID</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// We retrieve the attribute named id of the chapter element<br></span><span style="color: #9876AA">\$attr </span><span style="color: #007700">= </span><span style="color: #9876AA">\$doc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getElementsByTagName</span><span style="color: #007700">(</span><span style="color: #DD0000">'chapter'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">item</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">getAttributeNode</span><span style="color: #007700">(</span><span style="color: #DD0000">'id'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$attr</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isId</span><span style="color: #007700">()); </span><span style="color: #FF8000">// bool(true)<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 */
    public function isId(): bool {}

/**
 * <div id="dom-attr.rename" class="refentry"> <div class="refnamediv">  <h1 class="refname">Dom\Attr::rename</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">Dom\Attr::rename</span> — <span class="dc-title">Changes the qualified name or namespace of an attribute</span></p> </div> <div class="refsect1 description" id="refsect1-dom-attr.rename-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Dom\Attr::rename</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$namespaceURI</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$qualifiedName</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   This method changes the qualified name or namespace of an attribute.  </p> </div> <div class="refsect1 parameters" id="refsect1-dom-attr.rename-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">namespaceURI</span></dt>    <dd>     <span class="simpara">      The new namespace <span>URI</span> of the attribute.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">qualifiedName</span></dt>    <dd>     <span class="simpara">      The new qualified name of the attribute.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-dom-attr.rename-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-dom-attr.rename-errors">  <h3 class="title">错误／异常</h3>  <dl>       <dt><span class="classname"><a href="https://php.net/manual/zh/class.domexception.php" class="classname">DOMException</a></span> with code <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-namespace-err">Dom\NAMESPACE_ERR</a></span></strong></dt>    <dd>     <span class="simpara">      Raised if there is an error with the namespace, as determined by      <span class="parameter" style="color:#3A95FF">qualifiedName</span>.     </span>    </dd>          <dt><span class="classname"><a href="https://php.net/manual/zh/class.domexception.php" class="classname">DOMException</a></span> with code <strong><span><a href="https://php.net/manual/zh/dom.constants.php#constant.dom-invalid-modification-err">Dom\INVALID_MODIFICATION_ERR</a></span></strong></dt>    <dd>     <span class="simpara">      Raised if there already exists an attribute in the element with the same      qualified name.     </span>    </dd>     </dl> </div> <div class="refsect1 examples" id="refsect1-dom-attr.rename-examples">  <h3 class="title">示例</h3>  <div class="example" id="dom-attr.rename.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Dom\Attr::rename()</strong></span> example to change both the namespace and qualified name</strong></p>   <div class="example-contents"><p>    This changes the qualified name of <span class="literal">my-attr</span> to    <span class="literal">my-new-attr</span> and also changes its namespace to    <span class="literal">urn:my-ns</span>.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$doc </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\XMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">'&lt;root my-attr="value"/&gt;'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$root </span><span style="color: #007700">= </span><span style="color: #9876AA">\$doc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">documentElement</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$attribute </span><span style="color: #007700">= </span><span style="color: #9876AA">\$root</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">attributes</span><span style="color: #007700">[</span><span style="color: #DD0000">'my-attr'</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$attribute</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">rename</span><span style="color: #007700">(</span><span style="color: #DD0000">'urn:my-ns'</span><span style="color: #007700">, </span><span style="color: #DD0000">'my-new-attr'</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$doc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveXml</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;?xml&nbsp;version="1.0"&nbsp;encoding="UTF-8"?&gt;<br>&lt;root&nbsp;xmlns:ns1="urn:my-ns"&nbsp;ns1:my-new-attr="value"/&gt;</blockquote></div>   </div>  </div>  <div class="example" id="dom-attr.rename.example.only-name">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>Dom\Attr::rename()</strong></span> example to change only the qualified name</strong></p>   <div class="example-contents"><p>    This only changes the qualified name of <span class="literal">my-attr</span>    and keeps the namespace <span>URI</span> the same.   </p></div>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$doc </span><span style="color: #007700">= </span><span style="color: #9876AA">Dom\XMLDocument</span><span style="color: #007700">::</span><span style="color: #9876AA">createFromString</span><span style="color: #007700">(</span><span style="color: #DD0000">'&lt;root my-attr="value"/&gt;'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$root </span><span style="color: #007700">= </span><span style="color: #9876AA">\$doc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">documentElement</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$attribute </span><span style="color: #007700">= </span><span style="color: #9876AA">\$root</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">attributes</span><span style="color: #007700">[</span><span style="color: #DD0000">'my-attr'</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$attribute</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">rename</span><span style="color: #007700">(</span><span style="color: #9876AA">\$attribute</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">namespaceURI</span><span style="color: #007700">, </span><span style="color: #DD0000">'my-new-attr'</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$doc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">saveXml</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">&lt;?xml&nbsp;version="1.0"&nbsp;encoding="UTF-8"?&gt;<br>&lt;root&nbsp;my-new-attr="value"/&gt;</blockquote></div>   </div>  </div> </div> <div class="refsect1 notes" id="refsect1-dom-attr.rename-notes">  <h3 class="title">注释</h3>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    It is sometimes necessary to change the qualified name and namespace    <span>URI</span> together in one step to not break any    namespace rules.   </span>  </p></blockquote> </div> <div class="refsect1 seealso" id="refsect1-dom-attr.rename-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832"><strong>Dom\Element::rename()</strong></span></li>  </ul> </div></div>
