dt id="dom-documenttype.props.notations"><var class="varname">notations</var></dt>     <dd>      <span class="simpara">       A <span class="classname"><a href="https://php.net/manual/zh/class.dom-dtdnamednodemap.php" class="classname">Dom\DtdNamedNodeMap</a></span> containing the notations       declared in the <span>DTD</span>.      </span>     </dd>             <dt id="dom-documenttype.props.internalsubset"><var class="varname">internalSubset</var></dt><dd>      <p class="para">       The internal subset as a string, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if there is none. This       does not contain the delimiting square brackets.      </p>     </dd>       </dl>  </div> </div></div>
 * 
 * @since 8.4
 */
class DocumentType extends Node implements ChildNode
{
    public string $name;
    public DtdNamedNodeMap $entities;
    public DtdNamedNodeMap $notations;
    public string $publicId;
    public string $systemId;
    public ?string $internalSubset;


    public function remove(): void {}


    public function before(Node|string ...$nodes): void {}


    public function after(Node|string ...$nodes): void {}


    public function replaceWith(Node|string ...$nodes): void {}
}
